    minutes = 12, main_topics = '[{"title":{"en":"The 5 themes","am":"5ቱ ጭብጦች"},"points":[{"en":"A **theme** = the composition / main ideas of geography.","am":"**ጭብጥ** = የጂኦግራፊ ቅንብር / ዋና ሐሳቦች።"},{"en":"**Location, Place, Region, Human-Environment Interaction, Movement**.","am":"**አቀማመጥ፣ ቦታ፣ ቀጣና፣ የሰውና የአካባቢ መስተጋብር፣ እንቅስቃሴ**።"},{"en":"Memory trick: **MR. HELP**.","am":"የማስታወሻ ዘዴ፦ **MR. HELP**።"}]},{"title":{"en":"Location","am":"አቀማመጥ"},"points":[{"en":"Most geography studies **begin with location**.","am":"አብዛኞቹ የጂኦግራፊ ጥናቶች **በአቀማመጥ ይጀምራሉ**።"},{"en":"**Absolute** (astronomical) = latitude and longitude. **Relative** = surrounding land, water, countries.","am":"**ፍጹማዊ** (ሥነ ፈለካዊ) = ኬክሮስና ኬንትሮስ። **አንጻራዊ** = በዙሪያው ያለ የብስ፣ ውሃ፣ አገሮች።"},{"en":"Africa: **37°N–35°S**, **17°W–51°E**; Cape Bon (N), Cape Agulhas (S), Cape Guardafui (E), Cape Verde (W).","am":"አፍሪካ፦ **37°ሰ–35°ደ**፣ **17°ምዕ–51°ምሥ**፤ ኬፕ ቦን (ሰ)፣ ኬፕ አጉልሃስ (ደ)፣ ኬፕ ጓርዳፉይ (ምሥ)፣ ኬፕ ቨርድ (ምዕ)።"}]},{"title":{"en":"Place and Region","am":"ቦታና ቀጣና"},"points":[{"en":"**Place** = physical and human aspects of a location: **site and situation** (+ toponym).","am":"**ቦታ** = የአቀማመጥ የተፈጥሮና የሰው ገጽታዎች፦ **ስፍራና ሁኔታ** (+ የቦታ ስም)።"},{"en":"**Region** = an area with similar physical and human-made features.","am":"**ቀጣና** = ተመሳሳይ የተፈጥሮና ሰው ሠራሽ ገጽታዎች ያሉት አካባቢ።"},{"en":"Africa has 5 regions; Northern Africa is known for the young **Atlas fold mountains**.","am":"አፍሪካ 5 ቀጣናዎች አሏት፤ ሰሜን አፍሪካ በወጣቶቹ **የአትላስ የእጥፋት ተራሮች** ይታወቃል።"}]},{"title":{"en":"Interaction and Movement","am":"መስተጋብርና እንቅስቃሴ"},"points":[{"en":"Human-environment interaction: **Dependency, Adaptation, Modification** (D-A-M).","am":"የሰውና የአካባቢ መስተጋብር፦ **ጥገኝነት፣ መላመድ፣ ለውጥ ማድረግ** (D-A-M)።"},{"en":"Building a dam or terraces = **modification**.","am":"ግድብ ወይም እርከን መሥራት = **ለውጥ ማድረግ**።"},{"en":"Movement = people, **goods** and **ideas** moving from place to place.","am":"እንቅስቃሴ = ሰዎች፣ **ዕቃዎች** እና **ሐሳቦች** ከቦታ ቦታ መዘዋወር።"}]},{"title":{"en":"Two approaches","am":"ሁለቱ አቀራረቦች"},"points":[{"en":"An **approach** = a way or method of studying.","am":"**አቀራረብ** = የማጥኛ መንገድ ወይም ዘዴ።"},{"en":"**Regional** = one region, all its aspects (one place, many topics).","am":"**ቀጣናዊ** = አንድ ቀጣና፣ ሁሉም ገጽታዎቹ (አንድ ቦታ፣ ብዙ ርዕሶች)።"},{"en":"**Systematic (topical)** = one element across many places (one topic, many places).","am":"**ሥርዓታዊ (ርዕሰ ጉዳያዊ)** = አንድ ጉዳይ በብዙ ቦታዎች (አንድ ርዕስ፣ ብዙ ቦታዎች)።"}]}]'::jsonb, glossary = '[{"term":{"en":"Theme","am":"ጭብጥ"},"definition":{"en":"The composition or main ideas of geography, grouped into 5 themes.","am":"የጂኦግራፊ ቅንብር ወይም ዋና ሐሳቦች፤ በ5 ጭብጦች የተመደቡ።"}},{"term":{"en":"Location","am":"አቀማመጥ"},"definition":{"en":"A particular place or position; most geography studies begin with it.","am":"አንድ የተወሰነ ቦታ ወይም ስፍራ፤ አብዛኞቹ የጂኦግራፊ ጥናቶች በእሱ ይጀምራሉ።"}},{"term":{"en":"Absolute location","am":"ፍጹማዊ አቀማመጥ"},"definition":{"en":"The exact position of a place using latitude and longitude (also called astronomical or mathematical location).","am":"ኬክሮስንና ኬንትሮስን በመጠቀም የሚገለጽ ትክክለኛ የቦታ አቀማመጥ (ሥነ ፈለካዊ ወይም ሒሳባዊ አቀማመጥም ይባላል)።"}},{"term":{"en":"Relative location","am":"አንጻራዊ አቀማመጥ"},"definition":{"en":"The position of a place described by the landmasses, water bodies or countries around it.","am":"በዙሪያው ባሉ የየብስ ክፍሎች፣ የውሃ አካላት ወይም አገሮች የሚገለጽ የቦታ አቀማመጥ።"}},{"term":{"en":"Place","am":"ቦታ"},"definition":{"en":"The physical and human aspects of a location, described by its site and situation.","am":"የአንድ አቀማመጥ የተፈጥሮና የሰው ገጽታዎች፤ በስፍራውና በሁኔታው ይገለጻል።"}},{"term":{"en":"Site","am":"ስፍራ"},"definition":{"en":"The features of the place itself, such as land, soil and water.","am":"የቦታው ራሱ ገጽታዎች፣ እንደ መሬት፣ አፈርና ውሃ።"}},{"term":{"en":"Situation","am":"ሁኔታ"},"definition":{"en":"The environmental conditions of a place and its position in relation to its surroundings.","am":"የቦታው የአካባቢ ሁኔታዎችና ከዙሪያው አንጻር ያለው አቀማመጥ።"}},{"term":{"en":"Toponym","am":"የቦታ ስም"},"definition":{"en":"The name of a place.","am":"የአንድ ቦታ ስም።"}},{"term":{"en":"Region","am":"ቀጣና"},"definition":{"en":"A part of the Earth''s surface with similar physical and human-made features that set it apart from nearby areas.","am":"ከአጎራባች አካባቢዎች የሚለየው ተመሳሳይ የተፈጥሮና ሰው ሠራሽ ገጽታዎች ያሉት የምድር ገጽ ክፍል።"}},{"term":{"en":"Human-Environment Interaction","am":"የሰውና የአካባቢ መስተጋብር"},"definition":{"en":"How people and nature affect each other: dependency, adaptation and modification.","am":"ሰውና ተፈጥሮ እርስ በርስ እንዴት እንደሚነካኩ፦ ጥገኝነት፣ መላመድና ለውጥ ማድረግ።"}},{"term":{"en":"Modification","am":"ለውጥ ማድረግ"},"definition":{"en":"People changing the environment for their comfort, e.g. building dams or terraces.","am":"ሰዎች ለምቾታቸው አካባቢን መለወጣቸው፣ ለምሳሌ ግድብ ወይም እርከን መሥራት።"}},{"term":{"en":"Movement","am":"እንቅስቃሴ"},"definition":{"en":"The translocation of people, goods and ideas from one place to another.","am":"የሰዎች፣ የዕቃዎችና የሐሳቦች ከአንድ ቦታ ወደ ሌላ መዘዋወር።"}},{"term":{"en":"Regional approach","am":"ቀጣናዊ አቀራረብ"},"definition":{"en":"Studying all the physical and human aspects of one region.","am":"የአንድን ቀጣና ሁሉንም የተፈጥሮና የሰው ገጽታዎች ማጥናት።"}},{"term":{"en":"Systematic (topical) approach","am":"ሥርዓታዊ (ርዕሰ ጉዳያዊ) አቀራረብ"},"definition":{"en":"Studying one single element (topic) and how it varies from place to place; also called the topical approach.","am":"አንድን ነጠላ ጉዳይ (ርዕስ) እና ከቦታ ቦታ ያለውን ልዩነት ማጥናት፤ ርዕሰ ጉዳያዊ አቀራረብም ይባላል።"}}]'::jsonb
  where id = v_lesson_id;

  insert into public.lesson_sections (lesson_id, sort_order, title_en, title_am, icon, blocks) values
    (v_lesson_id, 1, 'What is a theme?', 'ጭብጥ ምንድን ነው?', 'layers',
     '[{"type":"keypoint","variant":"definition","title":{"en":"Theme","am":"ጭብጥ (Theme)"},"text":{"en":"In geography, a **theme** is the composition, or the main ideas, of the subject.","am":"በጂኦግራፊ **ጭብጥ (Theme)** ማለት የትምህርቱ ቅንብር ወይም ዋና ዋና ሐሳቦች ነው።"}},{"type":"paragraph","text":{"en":"Geography as a science is made of many ideas. They are grouped into **5 themes**, and each theme answers one big question.","am":"ጂኦግራፊ እንደ ሳይንስ ብዙ ሐሳቦችን ይዟል። እነዚህ በ**5 ጭብጦች** ይመደባሉ፤ እያንዳንዱ ጭብጥ አንድ ትልቅ ጥያቄ ይመልሳል።"}},{"type":"points","items":[{"icon":"map-pin","title":{"en":"Location","am":"አቀማመጥ (Location)"},"text":{"en":"Where is it?","am":"የት ነው ያለው?"}},{"icon":"landmark","title":{"en":"Place","am":"ቦታ (Place)"},"text":{"en":"What is it like there?","am":"እዚያ ምን ይመስላል?"}},{"icon":"map","title":{"en":"Region","am":"ቀጣና (Region)"},"text":{"en":"How are areas similar or different?","am":"አካባቢዎች እንዴት ይመሳሰላሉ ወይም ይለያያሉ?"}},{"icon":"sprout","title":{"en":"Human-Environment Interaction","am":"የሰውና የአካባቢ መስተጋብር (Human-Environment Interaction)"},"text":{"en":"How do people and nature affect each other?","am":"ሰውና ተፈጥሮ እርስ በርስ እንዴት ይነካካሉ?"}},{"icon":"route","title":{"en":"Movement","am":"እንቅስቃሴ (Movement)"},"text":{"en":"How do people, goods and ideas move?","am":"ሰዎች፣ ዕቃዎችና ሐሳቦች እንዴት ይንቀሳቀሳሉ?"}}]},{"type":"tip","title":{"en":"Memory trick","am":"የማስታወሻ ዘዴ"},"text":{"en":"**MR. HELP** = **M**ovement, **R**egion, **H**uman-**E**nvironment interaction, **L**ocation, **P**lace.","am":"**MR. HELP** = **M**ovement (እንቅስቃሴ)፣ **R**egion (ቀጣና)፣ **H**uman-**E**nvironment interaction (የሰውና የአካባቢ መስተጋብር)፣ **L**ocation (አቀማመጥ)፣ **P**lace (ቦታ)።"}}]'::jsonb),
    (v_lesson_id, 2, 'Theme 1: Location', 'ጭብጥ 1፦ አቀማመጥ', 'map-pin',
     '[{"type":"paragraph","text":{"en":"**Location** means a particular place or position. Most studies in geography **begin with this theme**.","am":"**አቀማመጥ (Location)** ማለት አንድ የተወሰነ ቦታ ወይም ስፍራ ነው። አብዛኞቹ የጂኦግራፊ ጥናቶች **በዚህ ጭብጥ ይጀምራሉ**።"}},{"type":"paragraph","text":{"en":"There are **2 methods** to locate a place:","am":"አንድን ቦታ ለማመልከት **2 ዘዴዎች** አሉ፦"}},{"type":"points","items":[{"icon":"compass","title":{"en":"Absolute location","am":"ፍጹማዊ አቀማመጥ (Absolute location)"},"text":{"en":"uses grid lines, **latitude** and **longitude**. It gives the exact position. Also called astronomical or mathematical location.","am":"የካርታ መረብ መስመሮችን፣ **ኬክሮስ (Latitude)** እና **ኬንትሮስ (Longitude)** ይጠቀማል። ትክክለኛውን ቦታ ይሰጣል። ሥነ ፈለካዊ ወይም ሒሳባዊ አቀማመጥም ይባላል።"}},{"icon":"map","title":{"en":"Relative location","am":"አንጻራዊ አቀማመጥ (Relative location)"},"text":{"en":"uses features around the place: landmasses, water bodies or neighbouring countries.","am":"በቦታው ዙሪያ ያሉ ነገሮችን ይጠቀማል፦ የየብስ ክፍሎችን፣ የውሃ አካላትን ወይም ጎረቤት አገሮችን።"}}]},{"type":"example","title":{"en":"Ethiopia''s location (textbook)","am":"የኢትዮጵያ አቀማመጥ (ከመማሪያ መጽሐፉ)"},"text":{"en":"Absolute: Ethiopia lies between **3°N–15°N** latitude and **33°E–48°E** longitude. Relative: it is in the Horn of Africa, with Sudan to the west and Kenya to the south.","am":"ፍጹማዊ፦ ኢትዮጵያ በ**3°ሰ–15°ሰ** ኬክሮስና በ**33°ምሥ–48°ምሥ** ኬንትሮስ መካከል ትገኛለች። አንጻራዊ፦ በአፍሪካ ቀንድ ውስጥ ናት፤ በምዕራብ ሱዳን፣ በደቡብ ኬንያ ያዋስኗታል።"}}]'::jsonb),
    (v_lesson_id, 3, 'Example: where is Africa?', 'ምሳሌ፦ አፍሪካ የት ናት?', 'earth',
     '[{"type":"paragraph","text":{"en":"Africa''s **absolute location** is shown by its 4 extreme points:","am":"የአፍሪካ **ፍጹማዊ አቀማመጥ** በ4ቱ ጫፍ ነጥቦቿ ይታያል፦"}},{"type":"table","caption":{"en":"The 4 extreme points of Africa","am":"የአፍሪካ 4ቱ ጫፍ ነጥቦች"},"headers":[{"en":"Direction","am":"አቅጣጫ"},{"en":"Extreme point","am":"ጫፍ ነጥብ"},{"en":"Country","am":"አገር"},{"en":"Degree","am":"ዲግሪ"}],"rows":[[{"en":"North","am":"ሰሜን"},{"en":"Cape Bon (Ras ben Sakka)","am":"ኬፕ ቦን (ራስ ቤን ሳካ)"},{"en":"Tunisia","am":"ቱኒዚያ"},{"en":"37°21''N","am":"37°21''ሰ"}],[{"en":"South","am":"ደቡብ"},{"en":"Cape Agulhas","am":"ኬፕ አጉልሃስ"},{"en":"South Africa","am":"ደቡብ አፍሪካ"},{"en":"34°52''S (about 35°S)","am":"34°52''ደ (35°ደ ገደማ)"}],[{"en":"East","am":"ምሥራቅ"},{"en":"Cape Guardafui (Ras Hafun area)","am":"ኬፕ ጓርዳፉይ (የራስ ሀፉን አካባቢ)"},{"en":"Somalia","am":"ሶማሊያ"},{"en":"51°28''E","am":"51°28''ምሥ"}],[{"en":"West","am":"ምዕራብ"},{"en":"Cape Verde (Cap-Vert)","am":"ኬፕ ቨርድ (ካፕ ቬር)"},{"en":"Senegal","am":"ሴኔጋል"},{"en":"17°33''W","am":"17°33''ምዕ"}]]},{"type":"keypoint","variant":"important","title":{"en":"Africa''s extent","am":"የአፍሪካ ስፋት"},"text":{"en":"Latitude **37°N – 35°S**, longitude **17°W – 51°E**. Africa is the only continent crossed by the Equator, the Prime Meridian and both Tropics, so it lies in **all four hemispheres**.","am":"ኬክሮስ **37°ሰ – 35°ደ**፣ ኬንትሮስ **17°ምዕ – 51°ምሥ**። ወገብ ምድር (Equator)፣ መነሻ ኬንትሮስ (Prime Meridian) እና ሁለቱም ትሮፒኮች የሚያቋርጡት ብቸኛው አህጉር አፍሪካ ነው፤ ስለዚህ በ**አራቱም ንፍቀ ክበቦች** ውስጥ ይገኛል።"}},{"type":"paragraph","text":{"en":"Africa''s **relative location**: the Mediterranean Sea to the north, the Red Sea to the north-east, the Atlantic Ocean to the west and the Indian Ocean to the east.","am":"የአፍሪካ **አንጻራዊ አቀማመጥ**፦ በሰሜን የሜዲትራኒያን ባሕር፣ በሰሜን ምሥራቅ ቀይ ባሕር፣ በምዕራብ አትላንቲክ ውቅያኖስ፣ በምሥራቅ ሕንድ ውቅያኖስ።"}},{"type":"keypoint","variant":"note","title":{"en":"Exam tip","am":"የፈተና ምክር"},"text":{"en":"Some books call the northern point **Ras ben Sakka** instead of Cape Bon, and some round 34°52''S to **35°S**. Both versions appear in exams.","am":"አንዳንድ መጻሕፍት ሰሜናዊውን ነጥብ ከኬፕ ቦን ይልቅ **ራስ ቤን ሳካ** ይሉታል፤ አንዳንዶቹም 34°52''ደ ን ወደ **35°ደ** ያጠጋጋሉ። ሁለቱም አጻጻፎች በፈተና ይመጣሉ።"}}]'::jsonb),
    (v_lesson_id, 4, 'Theme 2: Place', 'ጭብጥ 2፦ ቦታ', 'landmark',
     '[{"type":"keypoint","variant":"definition","title":{"en":"Place","am":"ቦታ (Place)"},"text":{"en":"**Place** is the physical and human aspects of a location: what a place is like. Every place has its own unique characteristics.","am":"**ቦታ (Place)** የአንድ አቀማመጥ የተፈጥሮና የሰው ገጽታዎች ናቸው፤ ቦታው ምን እንደሚመስል። እያንዳንዱ ቦታ የራሱ ልዩ ባሕርያት አሉት።"}},{"type":"table","caption":{"en":"A place is described by its site and situation (+ toponym)","am":"ቦታ የሚገለጸው በስፍራውና በሁኔታው ነው (+ የቦታ ስም)"},"headers":[{"en":"Term","am":"ቃል"},{"en":"Meaning","am":"ትርጉም"}],"rows":[[{"en":"Site","am":"ስፍራ (Site)"},{"en":"The features of the place itself: land, soil, water, etc.","am":"የቦታው ራሱ ገጽታዎች፦ መሬት፣ አፈር፣ ውሃ ወዘተ።"}],[{"en":"Situation","am":"ሁኔታ (Situation)"},{"en":"The environmental conditions of the place and its position in relation to its surroundings.","am":"የቦታው የአካባቢ ሁኔታዎችና ከዙሪያው ጋር ሲነጻጸር ያለው አቀማመጥ።"}],[{"en":"Toponym (textbook)","am":"የቦታ ስም (Toponym) (ከመማሪያ መጽሐፉ)"},{"en":"The name of a place.","am":"የአንድ ቦታ ስም።"}]]},{"type":"example","title":{"en":"Addis Ababa as a place","am":"አዲስ አበባ እንደ ቦታ"},"text":{"en":"Site: a high plateau, about 2,355 m, at the foot of Mount Entoto. Situation: near the centre of Ethiopia, where the main roads meet. Toponym: \"Addis Ababa\" means \"new flower\".","am":"ስፍራ፦ በእንጦጦ ተራራ ግርጌ፣ 2,355 ሜትር ገደማ ከፍታ ያለው ደጋማ ቦታ። ሁኔታ፦ ዋና ዋና መንገዶች በሚገናኙበት በኢትዮጵያ መሐል አካባቢ። የቦታ ስም፦ «አዲስ አበባ» (በእንግሊዝኛ \"New Flower\")።"}}]'::jsonb),
    (v_lesson_id, 5, 'Theme 3: Region', 'ጭብጥ 3፦ ቀጣና', 'map',
     '[{"type":"keypoint","variant":"definition","title":{"en":"Region","am":"ቀጣና (Region)"},"text":{"en":"A **region** is a part of the Earth''s surface with similar physical and human-made features, which make it different from the areas around it.","am":"**ቀጣና (Region)** ተመሳሳይ የተፈጥሮና ሰው ሠራሽ ገጽታዎች ያሉት፣ በዚህም ከዙሪያው አካባቢዎች የሚለይ የምድር ገጽ ክፍል ነው።"}},{"type":"table","headers":[{"en":"Kind of feature","am":"የገጽታ ዓይነት"},{"en":"Examples","am":"ምሳሌዎች"}],"rows":[[{"en":"Physical features","am":"የተፈጥሮ ገጽታዎች"},{"en":"Landforms (mountains, plains, valleys), climate, soil","am":"የመሬት ቅርጾች (ተራሮች፣ ሜዳዎች፣ ሸለቆዎች)፣ የአየር ንብረት፣ አፈር"}],[{"en":"Human-made features","am":"ሰው ሠራሽ ገጽታዎች"},{"en":"Settlement (dense or sparse), economy","am":"የሕዝብ አሰፋፈር (ጥቅጥቅ ወይም ስስ)፣ ኢኮኖሚ"}]]},{"type":"example","title":{"en":"Africa''s 5 regions","am":"የአፍሪካ 5 ቀጣናዎች"},"text":{"en":"Africa is divided into **Northern, Western, Central, Eastern and Southern** Africa. The well-known physical feature of Northern Africa is the young **Atlas fold mountains**.","am":"አፍሪካ በ**ሰሜን፣ ምዕራብ፣ መካከለኛ፣ ምሥራቅና ደቡብ** አፍሪካ ትከፈላለች። የሰሜን አፍሪካ ታዋቂው የተፈጥሮ ገጽታ ወጣቶቹ **የአትላስ የእጥፋት ተራሮች (Atlas fold mountains)** ናቸው።"}},{"type":"keypoint","variant":"note","title":{"en":"Textbook note","am":"የመማሪያ መጽሐፍ ማስታወሻ"},"text":{"en":"A **formal region** is the same throughout (e.g. same climate or language). A **functional (nodal) region** is linked to a central place, e.g. Addis Ababa linked with the other regions of Ethiopia.","am":"**መደበኛ ቀጣና (Formal region)** በሁሉም ቦታ ተመሳሳይ ነው (ለምሳሌ ተመሳሳይ የአየር ንብረት ወይም ቋንቋ)። **ተግባራዊ (ማዕከላዊ) ቀጣና (Functional/Nodal region)** ከአንድ ማዕከል ጋር የተሳሰረ ነው፤ ለምሳሌ አዲስ አበባ ከሌሎች የኢትዮጵያ አካባቢዎች ጋር ያላት ትስስር።"}}]'::jsonb),
    (v_lesson_id, 6, 'Theme 4: Human-Environment Interaction', 'ጭብጥ 4፦ የሰውና የአካባቢ መስተጋብር', 'sprout',
     '[{"type":"paragraph","text":{"en":"This theme is about how people interact with the natural environment. It has **3 aspects**:","am":"ይህ ጭብጥ ሰዎች ከተፈጥሮ አካባቢ ጋር እንዴት እንደሚገናኙ ይመለከታል። **3 ገጽታዎች** አሉት፦"}},{"type":"points","items":[{"icon":"tractor","title":{"en":"Dependency","am":"ጥገኝነት (Dependency)"},"text":{"en":"People **depend** on nature for a living: farming teff on highland soil, using river water.","am":"ሰዎች ለኑሮ በተፈጥሮ **ይመካሉ**፦ በደጋ አፈር ጤፍ ማረስ፣ የወንዝ ውሃ መጠቀም።"}},{"icon":"mountain-snow","title":{"en":"Adaptation","am":"መላመድ (Adaptation)"},"text":{"en":"People **adjust** their way of life to the environment: wearing a warm gabi in the cold highlands.","am":"ሰዎች አኗኗራቸውን ከአካባቢው ጋር **ያስማማሉ**፦ በቀዝቃዛ ደጋ ሞቅ ያለ ጋቢ መልበስ።"}},{"icon":"pickaxe","title":{"en":"Modification","am":"ለውጥ ማድረግ (Modification)"},"text":{"en":"People **change** the environment for their comfort: building dams, terracing hills, building cities.","am":"ሰዎች ለምቾታቸው አካባቢውን **ይለውጣሉ**፦ ግድብ መገንባት፣ ኮረብታዎችን እርከን መሥራት፣ ከተሞችን መገንባት።"}}]},{"type":"image","src":"/images/lessons/konso-terraces.webp","width":900,"height":604,"alt":{"en":"A green hillside near Konso in southern Ethiopia, cut into many stone-walled farming terraces with trees growing between them.","am":"በደቡብ ኢትዮጵያ ኮንሶ አቅራቢያ ያለ አረንጓዴ ኮረብታ፤ በድንጋይ ግድግዳ የተሠሩ ብዙ የእርሻ እርከኖችና በመካከላቸው ዛፎች።"},"caption":{"en":"Modification: farming terraces in the Konso Cultural Landscape, Ethiopia","am":"ለውጥ ማድረግ፦ በኮንሶ ባህላዊ መልክዓ ምድር፣ ኢትዮጵያ የሚገኙ የእርሻ እርከኖች"},"credit":"Photo: JosepMGracia · CC BY-SA 4.0 · Wikimedia Commons","creditUrl":"https://commons.wikimedia.org/wiki/File:Agricultural_terraces_in_the_Konso_Cultural_Landscape.jpg"},{"type":"tip","title":{"en":"Memory trick","am":"የማስታወሻ ዘዴ"},"text":{"en":"**D-A-M** = **D**ependency, **A**daptation, **M**odification. Think of a dam: people modifying a river.","am":"**D-A-M** = **D**ependency (ጥገኝነት)፣ **A**daptation (መላመድ)፣ **M**odification (ለውጥ ማድረግ)። ግድብን (Dam) አስቡ፦ ሰዎች ወንዝን ሲለውጡ።"}}]'::jsonb),
    (v_lesson_id, 7, 'Theme 5: Movement', 'ጭብጥ 5፦ እንቅስቃሴ', 'route',
     '[{"type":"keypoint","variant":"definition","title":{"en":"Movement","am":"እንቅስቃሴ (Movement)"},"text":{"en":"**Movement** is the translocation (moving) of people, their goods and their ideas from one place on Earth to another.","am":"**እንቅስቃሴ (Movement)** የሰዎች፣ የዕቃዎቻቸውና የሐሳቦቻቸው ከአንድ የምድር ቦታ ወደ ሌላ መዘዋወር ነው።"}},{"type":"paragraph","text":{"en":"It has **3 dimensions**:","am":"**3 ገጽታዎች** አሉት፦"}},{"type":"points","items":[{"icon":"users","title":{"en":"People","am":"ሰዎች"},"text":{"en":"physical movement, e.g. **migration**, which let humans live on every continent","am":"አካላዊ እንቅስቃሴ፣ ለምሳሌ **ፍልሰት (Migration)**፤ ሰዎች በሁሉም አህጉራት እንዲኖሩ ያስቻለ"}},{"icon":"ship","title":{"en":"Goods","am":"ዕቃዎች"},"text":{"en":"transport of goods, e.g. Ethiopian coffee exported to other countries","am":"የዕቃዎች ማጓጓዝ፣ ለምሳሌ የኢትዮጵያ ቡና ወደ ሌሎች አገሮች መላክ"}},{"icon":"lightbulb","title":{"en":"Ideas","am":"ሐሳቦች"},"text":{"en":"flow of ideas and information: news, the internet, religions, technology","am":"የሐሳብና የመረጃ ፍሰት፦ ዜና፣ ኢንተርኔት፣ ሃይማኖቶች፣ ቴክኖሎጂ"}}]},{"type":"example","title":{"en":"A cup of Ethiopian coffee","am":"አንድ ስኒ የኢትዮጵያ ቡና"},"text":{"en":"Coffee grown in Jimma or Sidama travels by truck to the port of Djibouti, then by ship to Europe. Recipes and coffee culture travel too, as ideas.","am":"በጅማ ወይም በሲዳማ የሚበቅል ቡና በከባድ መኪና ወደ ጅቡቲ ወደብ፣ ከዚያም በመርከብ ወደ አውሮፓ ይጓዛል። የቡና ባህልና አፈላል እንደ ሐሳብ አብረው ይጓዛሉ።"}}]'::jsonb),
    (v_lesson_id, 8, 'Approaches in geography', 'የጂኦግራፊ አቀራረቦች', 'scan-search',
     '[{"type":"keypoint","variant":"definition","title":{"en":"Approach","am":"አቀራረብ (Approach)"},"text":{"en":"An **approach** is a way, or method, of studying. Geography studies physical features, human-made aspects and how they interact.","am":"**አቀራረብ (Approach)** የማጥኛ መንገድ ወይም ዘዴ ነው። ጂኦግራፊ የተፈጥሮ ገጽታዎችን፣ ሰው ሠራሽ ገጽታዎችንና መስተጋብራቸውን ያጠናል።"}},{"type":"paragraph","text":{"en":"There are **2 approaches**:","am":"**2 አቀራረቦች** አሉ፦"}},{"type":"table","headers":[{"en":"Approach","am":"አቀራረብ"},{"en":"Studies","am":"የሚያጠናው"},{"en":"Example","am":"ምሳሌ"}],"rows":[[{"en":"Regional approach","am":"ቀጣናዊ አቀራረብ (Regional approach)"},{"en":"All the physical and human aspects of **one region**","am":"የ**አንድ ቀጣና** ሁሉንም የተፈጥሮና የሰው ገጽታዎች"},{"en":"Studying East Africa: its landforms, climate, people, economy","am":"ምሥራቅ አፍሪካን ማጥናት፦ የመሬት ቅርጹን፣ የአየር ንብረቱን፣ ሕዝቡን፣ ኢኮኖሚውን"}],[{"en":"Systematic (topical) approach","am":"ሥርዓታዊ (ርዕሰ ጉዳያዊ) አቀራረብ (Systematic/Topical approach)"},{"en":"**One single element** (topic) and how it varies from place to place","am":"**አንድ ነጠላ ጉዳይ** (ርዕስ) እና ከቦታ ቦታ እንዴት እንደሚለያይ"},{"en":"Studying only climate, or only population, across the world (e.g. economic, urban, cultural geography)","am":"የአየር ንብረትን ብቻ ወይም ሕዝብን ብቻ በዓለም ዙሪያ ማጥናት (ለምሳሌ ኢኮኖሚያዊ፣ ከተማ፣ ባህላዊ ጂኦግራፊ)"}]]},{"type":"tip","title":{"en":"Easy trick","am":"ቀላል ዘዴ"},"text":{"en":"**Regional** = one place, many topics. **Systematic** = one topic, many places.","am":"**ቀጣናዊ** = አንድ ቦታ፣ ብዙ ርዕሶች። **ሥርዓታዊ** = አንድ ርዕስ፣ ብዙ ቦታዎች።"}}]'::jsonb);

  insert into public.quizzes (lesson_id, title_en, title_am, description_en, description_am)
  values (v_lesson_id, 'Quiz: Themes and Approaches of Geography', 'ፈተና፦ የጂኦግራፊ ጭብጦችና አቀራረቦች', '20 questions on the 5 themes, Africa''s location and the two approaches.', 'ስለ 5ቱ ጭብጦች፣ ስለ አፍሪካ አቀማመጥና ስለ ሁለቱ አቀራረቦች 20 ጥያቄዎች።')
  returning id into v_quiz_id;

  insert into public.quiz_questions (quiz_id, sort_order, question_en, question_am, options_en, options_am, correct_index, explanation_en, explanation_am) values
    (v_quiz_id, 1, 'How many themes of geography are there?', 'ስንት የጂኦግራፊ ጭብጦች አሉ?',
     array['3', '4', '5', '6']::text[],
     array['3', '4', '5', '6']::text[],
     2, 'There are 5 themes: Location, Place, Region, Human-Environment Interaction and Movement (MR. HELP).', '5 ጭብጦች አሉ፦ አቀማመጥ፣ ቦታ፣ ቀጣና፣ የሰውና የአካባቢ መስተጋብርና እንቅስቃሴ (MR. HELP)።'),
    (v_quiz_id, 2, 'Which is NOT one of the themes of geography?', 'ከሚከተሉት ውስጥ የጂኦግራፊ ጭብጥ ያልሆነው የትኛው ነው?',
     array['Location', 'Movement', 'Region', 'Scope']::text[],
     array['አቀማመጥ (Location)', 'እንቅስቃሴ (Movement)', 'ቀጣና (Region)', 'ወሰን (Scope)']::text[],
     3, 'Scope means how much geography covers (lesson 1.1.3). It is not one of the 5 themes.', 'ወሰን ጂኦግራፊ ምን ያህል እንደሚሸፍን ያሳያል (ትምህርት 1.1.3)። ከ5ቱ ጭብጦች አንዱ አይደለም።'),
    (v_quiz_id, 3, 'Most studies of geography begin with which theme?', 'አብዛኞቹ የጂኦግራፊ ጥናቶች በየትኛው ጭብጥ ይጀምራሉ?',
     array['Place', 'Location', 'Region', 'Movement']::text[],
     array['ቦታ (Place)', 'አቀማመጥ (Location)', 'ቀጣና (Region)', 'እንቅስቃሴ (Movement)']::text[],
     1, 'Before anything else, geographers ask "where is it?", so most studies begin with location.', 'ከሁሉ በፊት የጂኦግራፊ ምሁራን «የት ነው?» ብለው ይጠይቃሉ፤ ስለዚህ አብዛኞቹ ጥናቶች በአቀማመጥ ይጀምራሉ።'),
    (v_quiz_id, 4, 'Locating a place using latitude and longitude is called:', 'ኬክሮስንና ኬንትሮስን በመጠቀም ቦታን ማመልከት ምን ይባላል?',
     array['Relative location', 'Absolute (astronomical) location', 'Situation', 'Region']::text[],
     array['አንጻራዊ አቀማመጥ', 'ፍጹማዊ (ሥነ ፈለካዊ) አቀማመጥ', 'ሁኔታ (Situation)', 'ቀጣና (Region)']::text[],
     1, 'Absolute location uses the grid lines of latitude and longitude to give the exact position.', 'ፍጹማዊ አቀማመጥ ትክክለኛውን ቦታ ለመስጠት የኬክሮስና የኬንትሮስ መስመሮችን ይጠቀማል።'),
    (v_quiz_id, 5, '"Africa lies south of the Mediterranean Sea" is an example of:', '«አፍሪካ ከሜዲትራኒያን ባሕር በስተደቡብ ትገኛለች» የምን ምሳሌ ነው?',
     array['Absolute location', 'Relative location', 'Toponym', 'Modification']::text[],
     array['ፍጹማዊ አቀማመጥ', 'አንጻራዊ አቀማመጥ', 'የቦታ ስም (Toponym)', 'ለውጥ ማድረግ (Modification)']::text[],
     1, 'It describes Africa by a nearby water body, not by degrees, so it is relative location.', 'አፍሪካን በዲግሪ ሳይሆን በአቅራቢያዋ ባለ የውሃ አካል ይገልጻል፤ ስለዚህ አንጻራዊ አቀማመጥ ነው።'),
    (v_quiz_id, 6, 'The northernmost point of Africa is:', 'የአፍሪካ ሰሜናዊ ጫፍ ነጥብ የትኛው ነው?',
     array['Cape Agulhas', 'Cape Verde', 'Cape Bon (Ras ben Sakka)', 'Cape Guardafui']::text[],
     array['ኬፕ አጉልሃስ', 'ኬፕ ቨርድ', 'ኬፕ ቦን (ራስ ቤን ሳካ)', 'ኬፕ ጓርዳፉይ']::text[],
     2, 'Cape Bon (also called Ras ben Sakka) in Tunisia, at about 37°N, is the northern extreme point.', 'በቱኒዚያ በ37°ሰ ገደማ የሚገኘው ኬፕ ቦን (ራስ ቤን ሳካም ይባላል) ሰሜናዊው ጫፍ ነጥብ ነው።'),
    (v_quiz_id, 7, 'Cape Agulhas, Africa''s southernmost point, is in:', 'የአፍሪካ ደቡባዊ ጫፍ ነጥብ ኬፕ አጉልሃስ የሚገኘው በየትኛው አገር ነው?',
     array['Somalia', 'Senegal', 'Tunisia', 'South Africa']::text[],
     array['ሶማሊያ', 'ሴኔጋል', 'ቱኒዚያ', 'ደቡብ አፍሪካ']::text[],
     3, 'Cape Agulhas (34°52''S, about 35°S) is in South Africa (RSA).', 'ኬፕ አጉልሃስ (34°52''ደ፣ 35°ደ ገደማ) በደቡብ አፍሪካ ይገኛል።'),
    (v_quiz_id, 8, 'The easternmost point of Africa, Cape Guardafui, is in:', 'የአፍሪካ ምሥራቃዊ ጫፍ ነጥብ ኬፕ ጓርዳፉይ የሚገኘው በየትኛው አገር ነው?',
     array['Kenya', 'Somalia', 'Ethiopia', 'Eritrea']::text[],
     array['ኬንያ', 'ሶማሊያ', 'ኢትዮጵያ', 'ኤርትራ']::text[],
     1, 'Cape Guardafui (Ras Hafun area), at about 51°E, is at the tip of the Horn of Africa in Somalia.', 'ኬፕ ጓርዳፉይ (የራስ ሀፉን አካባቢ) በ51°ምሥ ገደማ፣ በሶማሊያ በአፍሪካ ቀንድ ጫፍ ላይ ይገኛል።'),
    (v_quiz_id, 9, 'Africa lies longitudinally between:', 'አፍሪካ በኬንትሮስ ደረጃ የምትገኘው በየትኞቹ መካከል ነው?',
     array['17°W and 51°E', '37°N and 35°S', '20°W and 60°E', '0° and 51°E']::text[],
     array['17°ምዕ እና 51°ምሥ', '37°ሰ እና 35°ደ', '20°ምዕ እና 60°ምሥ', '0° እና 51°ምሥ']::text[],
     0, 'Longitude runs west–east: from Cape Verde (17°W) to Cape Guardafui (51°E). 37°N–35°S is the latitude.', 'ኬንትሮስ ከምዕራብ ወደ ምሥራቅ ይለካል፦ ከኬፕ ቨርድ (17°ምዕ) እስከ ኬፕ ጓርዳፉይ (51°ምሥ)። 37°ሰ–35°ደ ኬክሮሱ ነው።'),
    (v_quiz_id, 10, 'Which ocean lies to the EAST of Africa?', 'በአፍሪካ በስተ ምሥራቅ የሚገኘው ውቅያኖስ የትኛው ነው?',
     array['Atlantic Ocean', 'Pacific Ocean', 'Indian Ocean', 'Arctic Ocean']::text[],
     array['አትላንቲክ ውቅያኖስ', 'ፓሲፊክ ውቅያኖስ', 'ሕንድ ውቅያኖስ', 'አርክቲክ ውቅያኖስ']::text[],
     2, 'The Indian Ocean is to the east; the Atlantic Ocean is to the west.', 'ሕንድ ውቅያኖስ በምሥራቅ ነው፤ አትላንቲክ ውቅያኖስ በምዕራብ ነው።'),
    (v_quiz_id, 11, '"Place" refers to:', '«ቦታ (Place)» የሚያመለክተው፦',
     array['Only the name of a location', 'The physical and human aspects of a location', 'Only latitude and longitude', 'The movement of goods']::text[],
     array['የአንድን አቀማመጥ ስም ብቻ', 'የአንድ አቀማመጥ የተፈጥሮና የሰው ገጽታዎችን', 'ኬክሮስንና ኬንትሮስን ብቻ', 'የዕቃዎችን እንቅስቃሴ']::text[],
     1, 'Place describes what a location is like: its physical and human aspects.', 'ቦታ አንድ አቀማመጥ ምን እንደሚመስል ይገልጻል፦ የተፈጥሮና የሰው ገጽታዎቹን።'),
    (v_quiz_id, 12, 'A place is determined by its:', 'ቦታ የሚወሰነው በምንድን ነው?',
     array['Site and situation', 'Latitude and longitude', 'Adaptation and modification', 'Regional and systematic approach']::text[],
     array['ስፍራና ሁኔታ', 'ኬክሮስና ኬንትሮስ', 'መላመድና ለውጥ ማድረግ', 'ቀጣናዊና ሥርዓታዊ አቀራረብ']::text[],
     0, 'A place is described by its site (the place itself) and its situation (its surroundings and conditions).', 'ቦታ የሚገለጸው በስፍራው (ራሱ ቦታው) እና በሁኔታው (በዙሪያውና በአካባቢ ሁኔታዎቹ) ነው።'),
    (v_quiz_id, 13, 'A part of the Earth''s surface with similar physical and human features is a:', 'ተመሳሳይ የተፈጥሮና የሰው ገጽታዎች ያሉት የምድር ገጽ ክፍል ምን ይባላል?',
     array['Place', 'Site', 'Region', 'Location']::text[],
     array['ቦታ (Place)', 'ስፍራ (Site)', 'ቀጣና (Region)', 'አቀማመጥ (Location)']::text[],
     2, 'A region shares similar physical and human-made features that make it different from the areas around it.', 'ቀጣና ከዙሪያው የሚለይባቸው ተመሳሳይ የተፈጥሮና ሰው ሠራሽ ገጽታዎች አሉት።'),
    (v_quiz_id, 14, 'The well-known physical feature of the Northern Africa region is:', 'የሰሜን አፍሪካ ቀጣና ታዋቂው የተፈጥሮ ገጽታ የትኛው ነው?',
     array['The Rift Valley', 'The young Atlas fold mountains', 'The Drakensberg', 'Mount Kilimanjaro']::text[],
     array['የስምጥ ሸለቆ (Rift Valley)', 'ወጣቶቹ የአትላስ የእጥፋት ተራሮች', 'ድራከንስበርግ', 'ኪሊማንጃሮ ተራራ']::text[],
     1, 'The young Atlas fold mountains are in north-west Africa. The Rift Valley and Kilimanjaro are in Eastern Africa.', 'ወጣቶቹ የአትላስ ተራሮች በሰሜን ምዕራብ አፍሪካ ይገኛሉ። የስምጥ ሸለቆና ኪሊማንጃሮ በምሥራቅ አፍሪካ ናቸው።'),
    (v_quiz_id, 15, 'Building a dam on a river is an example of:', 'በወንዝ ላይ ግድብ መገንባት የምን ምሳሌ ነው?',
     array['Dependency', 'Adaptation', 'Modification', 'Situation']::text[],
     array['ጥገኝነት (Dependency)', 'መላመድ (Adaptation)', 'ለውጥ ማድረግ (Modification)', 'ሁኔታ (Situation)']::text[],
     2, 'A dam changes the environment for people''s comfort, so it is modification (think D-A-M).', 'ግድብ አካባቢን ለሰዎች ምቾት ይለውጣል፤ ስለዚህ ለውጥ ማድረግ ነው (D-A-M ን አስቡ)።'),
    (v_quiz_id, 16, 'Which is NOT a dimension of movement?', 'ከሚከተሉት ውስጥ የእንቅስቃሴ ገጽታ ያልሆነው የትኛው ነው?',
     array['Physical movement of people', 'Transport of goods', 'Flow of ideas', 'Modification of land']::text[],
     array['የሰዎች አካላዊ እንቅስቃሴ', 'የዕቃዎች ማጓጓዝ', 'የሐሳቦች ፍሰት', 'መሬትን መለወጥ']::text[],
     3, 'Movement = people, goods and ideas. Modification belongs to human-environment interaction.', 'እንቅስቃሴ = ሰዎች፣ ዕቃዎችና ሐሳቦች። ለውጥ ማድረግ የሰውና የአካባቢ መስተጋብር ክፍል ነው።'),
    (v_quiz_id, 17, 'The approach that studies ONE single element across many places is:', 'አንድን ነጠላ ጉዳይ በብዙ ቦታዎች የሚያጠናው አቀራረብ የትኛው ነው?',
     array['Regional approach', 'Systematic (topical) approach', 'Determinism', 'Possibilism']::text[],
     array['ቀጣናዊ አቀራረብ', 'ሥርዓታዊ (ርዕሰ ጉዳያዊ) አቀራረብ', 'ወሳኝነት (Determinism)', 'ዕድላዊነት (Possibilism)']::text[],
     1, 'Systematic = one topic, many places. Regional = one place, many topics.', 'ሥርዓታዊ = አንድ ርዕስ፣ ብዙ ቦታዎች። ቀጣናዊ = አንድ ቦታ፣ ብዙ ርዕሶች።'),
    (v_quiz_id, 18, 'Absolute location is also called:', 'ፍጹማዊ አቀማመጥ በሌላ ስም ምን ይባላል?',
     array['Astronomical or mathematical location', 'Situation', 'Toponym', 'Functional location']::text[],
     array['ሥነ ፈለካዊ ወይም ሒሳባዊ አቀማመጥ', 'ሁኔታ (Situation)', 'የቦታ ስም (Toponym)', 'ተግባራዊ አቀማመጥ']::text[],
     0, 'Because it uses the grid of latitude and longitude, absolute location is also called astronomical or mathematical location.', 'የኬክሮስና የኬንትሮስ መረብን ስለሚጠቀም ፍጹማዊ አቀማመጥ ሥነ ፈለካዊ ወይም ሒሳባዊ አቀማመጥም ይባላል።'),
    (v_quiz_id, 19, 'Farmers in the cold highlands wearing warm clothes like the gabi is an example of:', 'በቀዝቃዛ ደጋ የሚኖሩ ገበሬዎች እንደ ጋቢ ያሉ ሞቅ ያሉ ልብሶችን መልበሳቸው የምን ምሳሌ ነው?',
     array['Modification', 'Movement', 'Adaptation', 'Absolute location']::text[],
     array['ለውጥ ማድረግ (Modification)', 'እንቅስቃሴ (Movement)', 'መላመድ (Adaptation)', 'ፍጹማዊ አቀማመጥ']::text[],
     2, 'People adjust their way of life to the environment, so it is adaptation. They are not changing the environment itself.', 'ሰዎች አኗኗራቸውን ከአካባቢው ጋር ያስማማሉ፤ ስለዚህ መላመድ ነው። አካባቢውን ራሱ እየለወጡ አይደሉም።'),
    (v_quiz_id, 20, 'A geographer studies the landforms, climate, people and economy of East Africa only. Which approach is this?', 'አንድ የጂኦግራፊ ምሁር የምሥራቅ አፍሪካን የመሬት ቅርጽ፣ የአየር ንብረት፣ ሕዝብና ኢኮኖሚ ብቻ ያጠናል። ይህ የትኛው አቀራረብ ነው?',
     array['Systematic approach', 'Regional approach', 'Topical approach', 'Relative location']::text[],
     array['ሥርዓታዊ አቀራረብ', 'ቀጣናዊ አቀራረብ', 'ርዕሰ ጉዳያዊ አቀራረብ', 'አንጻራዊ አቀማመጥ']::text[],
     1, 'All aspects of one region = the regional approach (one place, many topics).', 'የአንድ ቀጣና ሁሉም ገጽታዎች = ቀጣናዊ አቀራረብ (አንድ ቦታ፣ ብዙ ርዕሶች)።');
end
$migration$;
